#Requires -RunAsAdministrator
# install-alloy-prod2.ps1 — GENERATED by prometheus_alloy_monitoring/deploy/alloy/windows/gen_windows.py
# Run on prod2 (10.10.10.12) as Administrator:  powershell -ExecutionPolicy Bypass -File .\install-alloy-prod2.ps1
# Installs Grafana Alloy v1.21.2 as Windows service "Alloy" → pushes this host's metrics to Prometheus
# on db1 and db2 (TLS + login). Nothing else on this server is changed.
# Uninstall: "C:\Program Files\GrafanaLabs\Alloy\uninstall.exe" /S ; Remove-NetFirewallRule -DisplayName 'Amfileon Alloy (db1 host-alive)'
$ErrorActionPreference = 'Stop'
$HostIP     = '10.10.10.12'
$Db1        = '10.10.10.20'
$Dir        = 'C:\ProgramData\Amfileon\alloy'
$InstallDir = 'C:\Program Files\GrafanaLabs\Alloy'
$Url        = 'https://github.com/grafana/alloy/releases/download/v1.21.2/alloy-installer-windows-amd64.exe.zip'
$Sha256     = '383b01ca3556c96a409b9488b1a9ef891b726db1d931c73f657613d21215548e'
